// Audit scans user-facing repository surfaces. It reports every unclassified
// old spelling, every stale allowlist rule, and every ambiguous rule.
func Audit(repoRoot string) error {
	matched := make([]int, len(RetainedOccurrences))
	var findings []string
	for _, rel := range []string{"README.md", "docs", "examples"} {
		path := filepath.Join(repoRoot, filepath.FromSlash(rel))
		info, err := os.Stat(path)
		if err != nil {
			return fmt.Errorf("managedocs: stat %s: %w", rel, err)
		}
		visit := func(path string, info fs.FileInfo) error {
			if info.IsDir() {
				return nil
			}
			switch strings.ToLower(filepath.Ext(path)) {
			case ".pyc", ".png", ".jpg", ".jpeg", ".gif", ".webp", ".pdf", ".zip", ".gz":
				return nil
			}
			file, err := os.Open(path)
			if err != nil {
				return err
			}
			defer file.Close()
			scanner := bufio.NewScanner(file)
			scanner.Buffer(make([]byte, 64*1024), 1024*1024)
			lineNo := 0
			for scanner.Scan() {
				lineNo++
				line := scanner.Text()
				if !strings.Contains(line, "fak guard") {
					continue
				}
				repoPath, err := filepath.Rel(repoRoot, path)
				if err != nil {
					return err
				}
				repoPath = filepath.ToSlash(repoPath)
				candidates := 0
				for i, allowed := range RetainedOccurrences {
					if allowed.Path == repoPath && allowed.Line == line {
						candidates++
						matched[i]++
					}
				}
				if candidates != 1 {
					findings = append(findings, fmt.Sprintf("%s:%d: unclassified or ambiguous occurrence: %s", repoPath, lineNo, strings.TrimSpace(line)))
				}
			}
			return scanner.Err()
		}
		if info.IsDir() {
			err = filepath.Walk(path, func(path string, info fs.FileInfo, walkErr error) error {
				if walkErr != nil {
					return walkErr
				}
				return visit(path, info)
			})
		} else {
			err = visit(path, info)
		}
		if err != nil {
			return fmt.Errorf("managedocs: scan %s: %w", rel, err)
		}
	}
	for i, allowed := range RetainedOccurrences {
		if strings.TrimSpace(allowed.Reason) == "" {
			findings = append(findings, fmt.Sprintf("%s: allowlist entry has no reason", allowed.Path))
		}
		want := allowed.Count
		if want == 0 {
			want = 1
		}
		if matched[i] != want {
			findings = append(findings, fmt.Sprintf("%s: stale allowlist entry matched %d occurrences; want %d", allowed.Path, matched[i], want))
		}
	}
	if len(findings) == 0 {
		return nil
	}
	sort.Strings(findings)
	return fmt.Errorf("managedocs ratchet failed:\n%s", strings.Join(findings, "\n"))
}
